      function inferApiCategory(name, baseUrl, notes, endpoints) {
        const key2 = String(name || "").trim().toLowerCase().replace(/\s+/g, "");
        if (apiCategoryByName[key2]) return apiCategoryByName[key2];
        const epStr = Array.isArray(endpoints) ? endpoints.slice(0, 20).map((e5) => `${e5.path || ""} ${e5.summary || ""}`).join(" ").toLowerCase() : "";
        const nLow = String(name || "").toLowerCase();
        const uLow = String(baseUrl || "").toLowerCase();
        const descLow = String(notes || "").toLowerCase();
        let best = "other";
        let bestScore = 0;
        for (const [catId, kws] of Object.entries(apiCategoryKeywords)) {
          let sc = 0;
          for (const kw of kws) {
            if (nLow.includes(kw) || key2.includes(kw)) sc += 6;
            if (uLow.includes(kw)) sc += 5;
            if (descLow.includes(kw)) sc += 3;
            if (epStr.includes(kw)) sc += 2;
          }
          if (sc > bestScore) {
            bestScore = sc;
            best = catId;
          }
        }
        return bestScore >= 3 ? best : "other";
      }
